changeSet.sql:
DROP MATERIALIZED VIEW IF EXISTS mv_daily_recon_summary;
ALTER TABLE settlements DROP CONSTRAINT IF EXISTS fk_settlements_trade;
ALTER TABLE recon_breaks DROP CONSTRAINT IF EXISTS fk_recon_breaks_trade;
ALTER TABLE trades RENAME TO trades_legacy_010;

CREATE TABLE trades (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    trade_ref       VARCHAR(30) NOT NULL,
    instrument_id   BIGINT NOT NULL REFERENCES instruments(id),
    counterparty_id BIGINT NOT NULL REFERENCES counterparties(id),
    asset_class     VARCHAR(20) NOT NULL,
    side            VARCHAR(4) NOT NULL,
    quantity        NUMERIC(18,4) NOT NULL,
    price           NUMERIC(18,4) NOT NULL,
    trade_date      DATE NOT NULL,
    status          VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    deleted_at      TIMESTAMP,
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modified_at     TIMESTAMP,
    CONSTRAINT pk_trades_010 PRIMARY KEY (id, trade_date),
    CONSTRAINT uq_trades_trade_ref_date_010 UNIQUE (trade_ref, trade_date)
) PARTITION BY RANGE (trade_date);

CREATE TABLE trades_2026_04 PARTITION OF trades
    FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE trades_2026_05 PARTITION OF trades
    FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE trades_2026_06 PARTITION OF trades
    FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE trades_2026_07 PARTITION OF trades
    FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE trades_default PARTITION OF trades DEFAULT;

CREATE INDEX idx_partitioned_trades_status_010 ON trades (status);
CREATE INDEX idx_partitioned_trades_instrument_010 ON trades (instrument_id);
CREATE INDEX idx_partitioned_trades_counterparty_010 ON trades (counterparty_id);

INSERT INTO trades (
    id, trade_ref, instrument_id, counterparty_id, asset_class, side,
    quantity, price, trade_date, status, deleted_at, created_at, modified_at
)
SELECT
    id, trade_ref, instrument_id, counterparty_id, asset_class, side,
    quantity, price, trade_date, status, deleted_at, created_at, modified_at
FROM trades_legacy_010;

SELECT setval(
    pg_get_serial_sequence('trades', 'id'),
    COALESCE((SELECT MAX(id) FROM trades), 1),
    true
);

DROP TABLE trades_legacy_010;

CREATE MATERIALIZED VIEW mv_daily_recon_summary AS
SELECT
    t.trade_date,
    c.region,
    i.asset_class,
    COUNT(*) AS total_trades,
    COUNT(*) FILTER (WHERE t.status = 'MATCHED') AS matched_trades,
    COALESCE(SUM(b.open_breaks), 0) AS open_breaks,
    ROUND(COALESCE(SUM(t.quantity * t.price), 0), 2) AS gross_notional,
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE t.status = 'MATCHED')
        / NULLIF(COUNT(*), 0),
        2
    ) AS match_rate_pct
FROM trades AS t
JOIN counterparties AS c ON c.id = t.counterparty_id
JOIN instruments AS i ON i.id = t.instrument_id
LEFT JOIN (
    SELECT trade_id, COUNT(*) FILTER (WHERE status = 'OPEN') AS open_breaks
    FROM recon_breaks
    GROUP BY trade_id
) AS b ON b.trade_id = t.id
WHERE t.deleted_at IS NULL
GROUP BY t.trade_date, c.region, i.asset_class
WITH NO DATA;

CREATE UNIQUE INDEX uq_mv_daily_recon_summary_dimensions
    ON mv_daily_recon_summary (trade_date, region, asset_class);
CREATE INDEX idx_mv_daily_recon_summary_date
    ON mv_daily_recon_summary (trade_date);
CREATE INDEX idx_mv_daily_recon_summary_region
    ON mv_daily_recon_summary (region);
REFRESH MATERIALIZED VIEW mv_daily_recon_summary;
